 <div class="modal" id="modal"><div class="modal-box"><div class="flower" id="modalFlower">🌷</div><h2 id="modalTitle">The garden is safe!</h2><p id="modalText"></p><button id="modalBtn">Play again</button></div></div>
 <script>
+(()=>{
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),W=800,H=600,S=50,C=16,R=12,goal={x:8,y:6};
+const $=id=>document.getElementById(id);let buildings=new Map(),enemies=[],shots=[],particles=[],wave=0,gold=180,health=100,stopped=0,mana=3,selected=null,wand=false,running=false,spawnLeft=0,spawnTimer=0,spawned=0,speed=1,last=0,toastTimer=0,ended=false,sound=true;
+const costs={tower:45,trap:30,wall:25,castle:65,moat:20},names={tower:'Petal tower',trap:'Vine snare',wall:'Hedge wall',castle:'Mini castle',moat:'Moat'};
+function say(text){const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1900)}
+function key(x,y){return `${x},${y}`}function blocked(x,y){const b=buildings.get(key(x,y));return b&&['tower','wall','castle'].includes(b.type)}
+function findPath(sx,sy){let start={x:sx,y:sy},q=[start],came=new Map([[key(sx,sy),null]]),dirs=[[1,0],[-1,0],[0,1],[0,-1]];while(q.length){let p=q.shift();if(p.x===goal.x&&p.y===goal.y)break;for(const [dx,dy] of dirs){let x=p.x+dx,y=p.y+dy,k=key(x,y);if(x<0||y<0||x>=C||y>=R||came.has(k)||blocked(x,y))continue;came.set(k,key(p.x,p.y));q.push({x,y})}}let g=key(goal.x,goal.y);if(!came.has(g)&&!(sx===goal.x&&sy===goal.y))return null;let path=[];while(g){const [x,y]=g.split(',').map(Number);path.push({x,y});g=came.get(g)}return path.reverse()}
+const edgeCells=()=>{let a=[];for(let x=0;x<C;x++){a.push([x,0],[x,R-1])}for(let y=1;y<R-1;y++)a.push([0,y],[C-1,y]);return a};
+function pathExistsEverywhere(){return edgeCells().every(([x,y])=>findPath(x,y))}
+function updateUI(){ $('healthText').innerHTML=`${Math.max(0,Math.ceil(health))} <em>/ 100</em>`;$('goldText').textContent=gold;$('waveText').innerHTML=`${wave} <em>/ 8</em>`;$('stoppedText').textContent=stopped;$('manaText').textContent=`${mana} / 3`;$('manaBar').style.width=`${mana/3*100}%`;$('dayNum').textContent=String(Math.max(1,wave)).padStart(2,'0');$('phase').textContent=running?'UNDER ATTACK':(ended?'COMPLETE':'PREP');$('phase').classList.toggle('danger',running);$('boardState').textContent=running?`WAVE ${wave} · ${enemies.length+spawnLeft} INTRUDERS`:'THE FLOWER MEADOW';$('boardHint').textContent=wand?'Tap a monkey to zap it!':selected?`Placing ${names[selected]} · tap an empty tile`:'Choose a defense, then tap a tile';$('waveBtn').disabled=running||ended;$('waveBtn').textContent=running?'🐒  Wave in progress':ended?'🌷  Garden saved':`▶  Start wave ${wave+1}`;document.querySelectorAll('.build-btn').forEach(b=>b.classList.toggle('active',b.dataset.build===selected));$('wandBtn').classList.toggle('on',wand);$('wandBtn').textContent=wand?'CANCEL':'USE WAND'}
+function startWave(){if(running||ended)return;if(wave>=8){finish(true);return}wave++;running=true;spawned=0;spawnLeft=4+wave*2;spawnTimer=.45;updateUI();say(`Wave ${wave} is here! Hold the garden!`)}
+function spawnEnemy(){let edges=edgeCells().filter(([x,y])=>!blocked(x,y)&&findPath(x,y));if(!edges.length){say('Every path is blocked!');spawnLeft=0;return}const [sx,sy]=edges[Math.floor(Math.random()*edges.length)],kind=wave>=3&&Math.random()<Math.min(.55,.18+wave*.04)?'swift':'monkey',p=findPath(sx,sy);enemies.push({x:sx*S+S/2,y:sy*S+S/2,path:p.slice(1),kind,hp:kind==='swift'?1:1+Math.floor((wave-1)/3),maxHp:kind==='swift'?1:1+Math.floor((wave-1)/3),speed:(kind==='swift'?62:39)+wave*2,progress:0,slow:0,hitFlash:0,tail:Math.random()*6.28});spawned++;spawnLeft--;}
+function beginBuild(t){if(ended)return;wand=false;selected=selected===t?null:t;updateUI()}
+function place(x,y){if(!selected)return;if(x<0||x>=C||y<0||y>=R)return;if(x===goal.x&&y===goal.y||Math.abs(x-goal.x)+Math.abs(y-goal.y)<=1){say('Keep the flower sanctuary clear!');return}if(buildings.has(key(x,y))){say('There is already something there.');return}if(gold<costs[selected]){say('Not enough petal coins!');return}let b={type:selected,hp:selected==='castle'?5:2,used:false,cool:0};buildings.set(key(x,y),b);if(['wall','castle','tower'].includes(selected)&&!pathExistsEverywhere()){buildings.delete(key(x,y));say('Leave a path open from every meadow edge!');return}gold-=costs[selected];selected=null;updateUI()}
+function zap(e){if(!wand)return;if(mana<1){say('Your wand needs a little more sparkle.');wand=false;updateUI();return}let hit=-1;for(let i=enemies.length-1;i>=0;i--)if(Math.hypot(e.x-enemies[i].x,e.y-enemies[i].y)<25){hit=i;break}if(hit<0){say('Aim right at a monkey!');return}let m=enemies[hit];mana--;killEnemy(hit,true);particles.push({x:m.x,y:m.y,t:0,type:'zap'});wand=false;updateUI()}
+function killEnemy(i,magic=false){const e=enemies[i];if(!e)return;enemies.splice(i,1);stopped++;gold+=magic?12:8;for(let n=0;n<6;n++)particles.push({x:e.x,y:e.y,t:0,type:'leaf',vx:(Math.random()-.5)*100,vy:(Math.random()-.7)*100});updateUI()}
+function damageFlower(amount){health=Math.max(0,health-amount);updateUI();if(health<=0)finish(false)}
+function finish(win){ended=true;running=false;$('modalFlower').textContent=win?'🌷':'🥀';$('modalTitle').textContent=win?'The garden is safe!':'Oh no, the tulip needs you!';$('modalText').textContent=win?`You protected your tulip through all 8 waves and stopped ${stopped} mischievous monkeys. The meadow is blooming again!`:`The monkeys reached the tulip. You stopped ${stopped} monkeys — rebuild your garden and give it another try.`;$('modal').classList.add('show');updateUI()}
+function reset(){buildings.clear();enemies=[];shots=[];particles=[];wave=0;gold=180;health=100;stopped=0;mana=3;selected=null;wand=false;running=false;spawnLeft=0;spawned=0;ended=false;$('modal').classList.remove('show');updateUI()}
+function cellAt(e){let r=canvas.getBoundingClientRect();return{x:Math.floor((e.clientX-r.left)*W/r.width/S),y:Math.floor((e.clientY-r.top)*H/r.height/S)}}
+canvas.addEventListener('pointerdown',e=>{let p=cellAt(e),wx=(e.clientX-canvas.getBoundingClientRect().left)*W/canvas.getBoundingClientRect().width,wy=(e.clientY-canvas.getBoundingClientRect().top)*H/canvas.getBoundingClientRect().height;if(wand){zap({x:wx,y:wy});return}if(selected){place(p.x,p.y);return}if(buildings.has(key(p.x,p.y))){let b=buildings.get(key(p.x,p.y));if(b.type==='wall'||b.type==='castle'||b.type==='tower'){say(`${names[b.type]} · sturdy garden defense`)}else if(b.type==='trap'){say(b.used?'This snare has sprung.':'A surprise for the monkeys!')}else say('A cool, slowing moat.');return}say('Pick a defense or use your wand!')});
+document.querySelectorAll('.build-btn').forEach(b=>b.addEventListener('click',()=>beginBuild(b.dataset.build)));$('wandBtn').addEventListener('click',()=>{if(mana<1){say('Your wand needs a little more sparkle.');return}wand=!wand;selected=null;updateUI()});$('waveBtn').addEventListener('click',startWave);$('speedBtn').addEventListener('click',()=>{speed=speed===1?2:1;$('speedBtn').textContent=`${speed}×`});$('modalBtn').addEventListener('click',reset);$('soundBtn').addEventListener('click',()=>{sound=!sound;$('soundBtn').textContent=sound?'♫':'♪';say(sound?'Garden sounds on':'Garden sounds off')});

