if(b.type==='tower'){ctx.fillStyle='#566c4c';ctx.beginPath();ctx.ellipse(cx,py+44,21,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b78d5a';ctx.fillRect(px+14,py+20,22,22);ctx.fillStyle='#e5c986';ctx.fillRect(px+17,py+17,16,24);ctx.fillStyle='#6d8d59';ctx.beginPath();ctx.moveTo(px+10,py+20);ctx.lineTo(cx,py+5);ctx.lineTo(px+40,py+20);ctx.fill();ctx.fillStyle='#c76247';ctx.beginPath();ctx.arc(cx,py+17,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#725847';ctx.fillRect(px+22,py+32,7,10);}}
